import { OBJExporter } from 'three/examples/jsm/exporters/OBJExporter.js';
import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js';
import fs from 'fs';
import path from 'path';
import { createScene } from './data/object.js';

// Create the scene
const root = createScene();

// Update all world matrices
root.updateMatrixWorld(true);

// Rotation matrix for Blender Z-up space (-90 degrees around X axis)
const blenderRotation = new THREE.Matrix4().makeRotationX(-Math.PI / 2);

// Collect all geometries with world transforms applied
const geometries = [];

root.traverse((obj) => {
  if (obj instanceof THREE.InstancedMesh) {
    // Handle InstancedMesh - extract each instance as a separate geometry
    const instanceMatrix = new THREE.Matrix4();
    for (let i = 0; i < obj.count; i++) {
      obj.getMatrixAt(i, instanceMatrix);
      const geom = obj.geometry.clone();
      // Apply instance matrix, then world matrix of the parent, then Blender rotation
      const combinedMatrix = new THREE.Matrix4()
        .copy(blenderRotation)
        .multiply(obj.matrixWorld)
        .multiply(instanceMatrix);
      geom.applyMatrix4(combinedMatrix);
      geometries.push(geom);
    }
  } else if (obj instanceof THREE.Mesh) {
    const geom = obj.geometry.clone();
    // Apply world transform then Blender rotation
    const combinedMatrix = new THREE.Matrix4()
      .copy(blenderRotation)
      .multiply(obj.matrixWorld);
    geom.applyMatrix4(combinedMatrix);
    geometries.push(geom);
  }
});

// Merge all geometries
const mergedGeometry = mergeGeometries(geometries);
const exportMesh = new THREE.Mesh(mergedGeometry);

// Export to OBJ
const exporter = new OBJExporter();
const objData = exporter.parse(exportMesh);

// Ensure output directory exists
const outputDir = '/root/output';
if (!fs.existsSync(outputDir)) {
  fs.mkdirSync(outputDir, { recursive: true });
}

// Write the OBJ file
const outputPath = path.join(outputDir, 'object.obj');
fs.writeFileSync(outputPath, objData);

console.log(`Successfully exported to ${outputPath}`);

